<?php class Database { private $connection; private $db_path; public function __construct($db_path = 'database/sinav.db') { $this->db_path = $db_path; $this->connect(); } private function connect() { try { $this->connection = new PDO('sqlite:' . $this->db_path); $this->connection->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION); } catch (PDOException $e) { die('Database connection failed: ' . $e->getMessage()); } } public function getConnection() { return $this->connection; } public function query($sql, $params = []) { $stmt = $this->connection->prepare($sql); $stmt->execute($params); return $stmt; } public function insert($table, $data) { $columns = implode(', ', array_keys($data)); $placeholders = implode(', ', array_fill(0, count($data), '?')); $sql = "INSERT INTO $table ($columns) VALUES ($placeholders)"; return $this->query($sql, array_values($data)); } public function update($table, $data, $where) { $set = implode(', ', array_map(fn($k) => "$k = ?", array_keys($data))); $sql = "UPDATE $table SET $set WHERE $where"; return $this->query($sql, array_values($data)); } public function delete($table, $where) { $sql = "DELETE FROM $table WHERE $where"; return $this->connection->exec($sql); } public function select($table, $where = null, $limit = null) { $sql = "SELECT * FROM $table"; if ($where) $sql .= " WHERE $where"; if ($limit) $sql .= " LIMIT $limit"; return $this->query($sql)->fetchAll(PDO::FETCH_ASSOC); } } ?>